-- Wanderlens Travel Gallery: per-photo content (run after the batch add)
UPDATE cpg133_pictures SET title='Zermatt Mascot', caption='Every shop on the Bahnhofstrasse seems to have one of these parked outside. He did not move once in twenty minutes.', hits=312, votes=3, pic_rating=9333, mtime=FROM_UNIXTIME(ctime) WHERE filepath='alps/' AND filename='IMG_4237.JPG';
UPDATE cpg133_pictures SET title='Matterhorn from Gornergrat', caption='First train up, 7am. Worth every franc of the ridiculous ticket price.', hits=941, votes=6, pic_rating=9667, mtime=FROM_UNIXTIME(ctime) WHERE filepath='alps/' AND filename='IMG_4265.JPG';
UPDATE cpg133_pictures SET title='Alpine Flowers', caption='Lying on my stomach in a meadow above Riffelalp to get this one. Glad nobody I know walked past.', hits=402, votes=3, pic_rating=8667, mtime=FROM_UNIXTIME(ctime) WHERE filepath='alps/' AND filename='IMG_1852.JPG';
UPDATE cpg133_pictures SET title='Lake above Zermatt', caption='One of the little lakes on the Five Lakes walk. Freezing, and yes, I went in up to my knees.', hits=266, votes=2, pic_rating=9000, mtime=FROM_UNIXTIME(ctime) WHERE filepath='alps/' AND filename='IMG_1872.JPG';
UPDATE cpg133_pictures SET title='Rhone Glacier', caption='The Hotel Belvedere on the Furka Pass road, practically sitting on the ice. You can walk into a tunnel cut in the glacier for a few francs.', hits=227, votes=1, pic_rating=8000, mtime=FROM_UNIXTIME(ctime) WHERE filepath='alps/' AND filename='IMG_1899.JPG';
UPDATE cpg133_pictures SET title='Ridge Walk, Carnic Alps', caption='Last day of the trip, on the Austrian-Italian border. Nine hours, two litres of water, zero regrets.', hits=158, votes=2, pic_rating=9000, mtime=FROM_UNIXTIME(ctime) WHERE filepath='alps/' AND filename='IMG_1926.JPG';
UPDATE cpg133_pictures SET title='Green Mountains at Sunrise', caption='Frost on the car, mist on the river, and the hills lit up orange for about ten minutes. Route 100, Vermont.', hits=287, votes=4, pic_rating=9500, mtime=FROM_UNIXTIME(ctime) WHERE filepath='newengland/' AND filename='IMG_1944.JPG';
UPDATE cpg133_pictures SET title='Kancamagus Highway', caption='Pulled over at every single overlook on the Kancamagus. This was the best of them.', hits=198, votes=2, pic_rating=8000, mtime=FROM_UNIXTIME(ctime) WHERE filepath='newengland/' AND filename='IMG_4286.JPG';
UPDATE cpg133_pictures SET title='Eagle Lake, Acadia', caption='Eagle Lake from the carriage road. Peak colour was a week earlier, but nobody told the maples by the water.', hits=173, votes=2, pic_rating=9000, mtime=FROM_UNIXTIME(ctime) WHERE filepath='newengland/' AND filename='IMG_1963.JPG';
UPDATE cpg133_pictures SET title='Birches, Acadia', caption='', hits=96, votes=0, pic_rating=0, mtime=FROM_UNIXTIME(ctime) WHERE filepath='newengland/' AND filename='IMG_1974.JPG';
UPDATE cpg133_pictures SET title='View from Gorham Mountain', caption='Short climb, huge view. Otter Cliff and the ocean on the left.', hits=141, votes=1, pic_rating=8000, mtime=FROM_UNIXTIME(ctime) WHERE filepath='newengland/' AND filename='IMG_1984.JPG';
UPDATE cpg133_pictures SET title='Jemaa el-Fnaa Storytellers', caption='Every evening the square fills up with storytellers, musicians, snake charmers and food stalls. Nobody seemed to mind the camera as long as you dropped a few dirhams in the hat.', hits=384, votes=3, pic_rating=9333, mtime=FROM_UNIXTIME(ctime) WHERE filepath='morocco/' AND filename='IMG_4309.JPG';
UPDATE cpg133_pictures SET title='Souk Semmarine', caption='The main covered street into the souks. The light through the slats was the best thing about it.', hits=205, votes=2, pic_rating=8000, mtime=FROM_UNIXTIME(ctime) WHERE filepath='morocco/' AND filename='IMG_2012.JPG';
UPDATE cpg133_pictures SET title='Storks on the Wall', caption='Storks nest all along the walls of the Badi Palace. They clatter their beaks like castanets.', hits=117, votes=1, pic_rating=8000, mtime=FROM_UNIXTIME(ctime) WHERE filepath='morocco/' AND filename='IMG_2021.JPG';
UPDATE cpg133_pictures SET title='A Door in the Medina', caption='', hits=88, votes=0, pic_rating=0, mtime=FROM_UNIXTIME(ctime) WHERE filepath='morocco/' AND filename='IMG_2047.JPG';
UPDATE cpg133_pictures SET title='Chefchaouen Rooftops', caption='Six hours on a CTM bus from Fes to get here. The whole town is painted blue and it is very quiet after Marrakech.', hits=263, votes=2, pic_rating=10000, mtime=FROM_UNIXTIME(ctime) WHERE filepath='morocco/' AND filename='IMG_2064.JPG';
UPDATE cpg133_pictures SET title='Chouara Tannery, Fes', caption='They hand you a sprig of mint at the door for the smell. You need it.', hits=349, votes=3, pic_rating=8667, mtime=FROM_UNIXTIME(ctime) WHERE filepath='morocco/' AND filename='IMG_2075.JPG';
UPDATE cpg133_pictures SET title='Rabelo Boats, Porto', caption='The old port wine boats moored in front of the lodges in Vila Nova de Gaia. Tasting tours every half hour, which explains the rest of the afternoon.', hits=176, votes=2, pic_rating=8000, mtime=FROM_UNIXTIME(ctime) WHERE filepath='portugal/' AND filename='IMG_4331.JPG';
UPDATE cpg133_pictures SET title='Tram, Lisbon', caption='The trams climb streets you would not want to walk up. Rua da Bica at dusk.', hits=239, votes=2, pic_rating=9000, mtime=FROM_UNIXTIME(ctime) WHERE filepath='portugal/' AND filename='IMG_4347.JPG';
UPDATE cpg133_pictures SET title='Belem Tower', caption='', hits=152, votes=1, pic_rating=8000, mtime=FROM_UNIXTIME(ctime) WHERE filepath='portugal/' AND filename='IMG_2096.JPG';
UPDATE cpg133_pictures SET title='Monserrate Palace, Sintra', caption='Less famous than the Pena Palace and twice as nice. We had the gardens almost to ourselves.', hits=131, votes=1, pic_rating=10000, mtime=FROM_UNIXTIME(ctime) WHERE filepath='portugal/' AND filename='IMG_4370.JPG';
UPDATE cpg133_pictures SET title='Cabo da Roca', caption='Westernmost point of mainland Europe. You can buy a certificate that says you were here. We did not.', hits=219, votes=2, pic_rating=9000, mtime=FROM_UNIXTIME(ctime) WHERE filepath='portugal/' AND filename='IMG_4389.JPG';
UPDATE cpg133_pictures SET title='Cliffs near Sagres', caption='Western Algarve in February: wind, sun, surfers, and nobody else.', hits=187, votes=3, pic_rating=8667, mtime=FROM_UNIXTIME(ctime) WHERE filepath='portugal/' AND filename='IMG_2106.JPG';
UPDATE cpg133_pictures SET title='Senso-ji at Night', caption='Asakusa after the shops close. The temple stays lit up and the crowds disappear.', hits=214, votes=3, pic_rating=9333, mtime=FROM_UNIXTIME(ctime) WHERE filepath='tokyo/' AND filename='DSC_1116.JPG';
UPDATE cpg133_pictures SET title='Shinjuku East Exit', caption='Rush hour outside Shinjuku station. The pedestrian lights change and about a thousand people cross at once.', hits=306, votes=2, pic_rating=9000, mtime=FROM_UNIXTIME(ctime) WHERE filepath='tokyo/' AND filename='IMG_4403.JPG';
UPDATE cpg133_pictures SET title='Nishi-Shinjuku Towers', caption='From the free observation deck at the Metropolitan Government Building.', hits=162, votes=1, pic_rating=8000, mtime=FROM_UNIXTIME(ctime) WHERE filepath='tokyo/' AND filename='IMG_4411.JPG';
UPDATE cpg133_pictures SET title='Shibuya Side Street', caption='Center Gai, just up from the big crossing. Karaoke, pachinko and a lot of noise.', hits=251, votes=2, pic_rating=8000, mtime=FROM_UNIXTIME(ctime) WHERE filepath='tokyo/' AND filename='DSC_1144.JPG';
UPDATE cpg133_pictures SET title='Tokyo Tower', caption='Tokyo Tower from the 40th floor of the World Trade Center building in Hamamatsucho, tripod jammed against the glass.', hits=288, votes=3, pic_rating=9333, mtime=FROM_UNIXTIME(ctime) WHERE filepath='tokyo/' AND filename='DSC_1163.JPG';
UPDATE cpg133_pictures SET title='Bangkok Tuk-Tuk', caption='Lined up outside a gem shop on Charoen Krung. Every driver had a cousin with a tailor''s shop.', hits=142, votes=1, pic_rating=8000, mtime=FROM_UNIXTIME(ctime) WHERE filepath='seasia/' AND filename='IMG_2117.JPG';
UPDATE cpg133_pictures SET title='Floating Market, Bangkok', caption='Damnoen Saduak, two hours out of Bangkok. Get there before eight, before the tour buses.', hits=212, votes=3, pic_rating=8667, mtime=FROM_UNIXTIME(ctime) WHERE filepath='seasia/' AND filename='IMG_2129.JPG';
UPDATE cpg133_pictures SET title='Chiang Mai Night Bazaar', caption='Bought far too many cushion covers here.', hits=129, votes=1, pic_rating=8000, mtime=FROM_UNIXTIME(ctime) WHERE filepath='seasia/' AND filename='IMG_4432.JPG';
UPDATE cpg133_pictures SET title='Luang Prabang Morning Market', caption='Up at 5:30 for the monks'' alms round (no photos, it felt wrong), then breakfast wandering through the market.', hits=301, votes=3, pic_rating=9333, mtime=FROM_UNIXTIME(ctime) WHERE filepath='seasia/' AND filename='IMG_2138.JPG';
UPDATE cpg133_pictures SET title='Angkor Wat Sunrise', caption='Worth getting up at 4:30am for. Shot from the edge of the north reflecting pool with about two hundred other people.', hits=318, votes=10, pic_rating=8400, mtime=FROM_UNIXTIME(ctime) WHERE filepath='seasia/' AND filename='IMG_2164.JPG';
UPDATE cpg133_pictures SET title='Siem Reap Market Stalls', caption='Phnom Krom, on the road down to the Tonle Sap floating villages.', hits=88, votes=1, pic_rating=8000, mtime=FROM_UNIXTIME(ctime) WHERE filepath='seasia/' AND filename='IMG_2190.JPG';
UPDATE cpg133_pictures SET title='Phnom Penh Riverside', caption='Sisowath Quay in the late afternoon heat. The FCC bar is a few doors down.', hits=63, votes=0, pic_rating=0, mtime=FROM_UNIXTIME(ctime) WHERE filepath='seasia/' AND filename='IMG_4456.JPG';
UPDATE cpg133_pictures SET title='Mekong Delta Boats', caption='Two days on boats around Ben Tre and Can Tho. Most of the delta seems to get around this way.', hits=97, votes=1, pic_rating=8000, mtime=FROM_UNIXTIME(ctime) WHERE filepath='seasia/' AND filename='IMG_2202.JPG';
UPDATE cpg133_pictures SET title='Hoi An Lanterns', caption='It rained all afternoon and the lanterns in the old town came on early.', hits=176, votes=2, pic_rating=9000, mtime=FROM_UNIXTIME(ctime) WHERE filepath='seasia/' AND filename='IMG_2224.JPG';
UPDATE cpg133_pictures SET title='Halong Bay Limestone Cliffs', caption='Evening on the junk, anchored between the islands.', hits=254, votes=3, pic_rating=9333, mtime=FROM_UNIXTIME(ctime) WHERE filepath='seasia/' AND filename='IMG_2232.JPG';
