INSERT INTO cpg133_comments (pid, msg_author, msg_body, msg_date, msg_raw_ip, msg_hdr_ip, author_md5_id, author_id) VALUES ((SELECT pid FROM cpg133_pictures WHERE filepath='seasia/' AND filename='IMG_2164.JPG'), 'tgoodwin', 'Great exposure on this one. Did you meter off the sky or the towers? Mine all came out either blown out or too dark.', '2005-05-30 19:52:00', '54.59.176.34', '54.59.176.34', '94895b8e77e06f653ac80de020555610', 0);
