INSERT INTO cpg133_comments (pid, msg_author, msg_body, msg_date, msg_raw_ip, msg_hdr_ip, author_md5_id, author_id) VALUES ((SELECT pid FROM cpg133_pictures WHERE filepath='seasia/' AND filename='IMG_2232.JPG'), 'danwalsh', 'Booked it through our guesthouse in Hanoi for $38 each, one night on board. Food was fine, cabins were small, views were not.', '2005-05-30 22:40:00', '66.74.59.96', '66.74.59.96', '', 1);
